			/*initBntTrxlBuRqMngReg*/			
           DELETE FROM BNTTRXL
           WHERE DOC_NAME = 'BURQ_MNG'
             AND TARGET = #{USER_ID}
             AND KEY_1 = #{st_burq_no}


/*updateMasterMpRqBulkQuotationMngReg*/
UPDATE KEP_BURQ_ITEM
SET AGENT_MNG_USER_ID = #{AGENT_MNG_USER_ID},							
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{USER_ID}
WHERE BURQ_NO = #{st_burq_no}
AND AGENT = #{AGENT_CODE}


/* updateMasterMpRqBulkQuotationProjectStatus_2 */
UPDATE KEP_BURQ_MNG
SET PROJECT_STATUS = DECODE(RFQ_START_DATE,NULL,'B',PROJECT_STATUS),
	RFQ_START_DATE =  DECODE(RFQ_START_DATE,NULL,SYSDATE,RFQ_START_DATE),
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{USER_ID}
WHERE BURQ_NO = #{st_burq_no}
